		int count = 0;
		ArrayList<Integer> numList = new ArrayList<>();
		ArrayList<Integer> backdoor = new ArrayList<>();
		for (int i=1; i<=n; i++) {
			count += (i - 1) / 2;
			numList.add(i);
		}

